def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Trim a PCM interview WAV and create chapter files and metadata."
    )
    parser.add_argument("wav", type=Path, help="source PCM WAV file")
    parser.add_argument("transcript", type=Path, help="source transcript CSV")
    parser.add_argument("--output", required=True, type=Path, help="output directory")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        process(args.wav, args.transcript, args.output)
    except (OSError, ValueError, wave.Error, csv.Error) as exc:
        raise SystemExit(f"error: {exc}") from exc
    return 0


